    def isMatch(self, s: str, p: str) -> bool:
        m= len(s)
        n= len(p)

        dp = [[False]*(n+1) for i in range(m+1)]

        dp[0][0] = True

        for j in range(len(p)):
            if p[j] == "*":
                dp[0][j+1] = dp[0][j]

        for i in range(1,m+1):
